#!/usr/bin/env python3
"""Generates the instance-side witness matrix fixture (#536 step 3) and its
expected output, which is computed here from the rules of World::witnesses,
not taken from a run.

  gen_matrix.py TARGET OUT.qz OUT.out      TARGET: class_scoped | class_top | class_args | generic_scoped | generic_top | abstract | module | typed
"""
import sys

HEADER = """# The #536 step 3 witness matrix, instance side, target `{target}`{note}
# (generated by tools/witness-matrix.py; the class side is
# witness_matrix_class/_generic/_abstract,
# the cross-cog column is in cogs.rs, the refusals in diagnostics.rs):
# conformance path x witness source x requirement x module arguments x
# scope of the extension, each cell printing what runs through a value
# typed `M` in a function at the top level (elsewhere, for a scoped
# extension), through one in the extension's module (where it is
# active), and for a direct call on a receiver typed as the conforming
# class where the extension is active. The expected output was computed
# from the rules, not taken from a run. For a class `K` that has `M`
# only through an extension, a call through `M` runs the first found
# going up `K`'s order: at a class or module, the own method of an
# extension of it that brings `M`, else its own method that the override
# table pairs with `M`'s (a subclass's own, one of a module the class or
# a subclass includes itself, the included module `N` over the `M` it
# brings); then `M`'s own body. So below the class the conformance hangs
# from, a subclass's own method or its own include's comes first; at
# that class the extension's method comes before the class's own; for a
# module target, the including class's own comes before the extension's,
# which comes before the module's own. A direct call where the extension
# is active runs the extension's own method when it has one (chosen
# statically, also on a subclass's value typed as the class), else what
# the call through `M` runs. An own include (path `own`) goes by
# ordinary dispatch. The table takes no witness the override table does
# not pair: witness_matrix_typed has the cells that would show one.
# Skipped as identical by the rules or not expressible:
{skipped}"""

SKIPPED = {
    "class": [
        "args param: no class parameter to pass (generic target)",
        "path own with a subclass's value: ordinary dispatch, one class down",
        "args concrete beyond the reduced list of _class_args, and the reduced lists of the subclass paths: the same rule cell by cell as path ext x args none (one file per scope keeps the checker's time down)",
        "path own x witness ext/emod/nmod/prev: no extension (cell 1's extension method is in extension_own_include_method)",
        "witness default x requirement abstract: nothing implements it (#600)",
        "the gated sends (`sort`, `clamp`): they look the name up first (#599)",
        "witnesses the override table does not pair (a module the extension includes beside `M`, a method the class inherits for an abstract one): none in this table, left to their own pull requests (#557's family); extension_witness_other_module has the pair the override table does have",
        "an extension's own method that includes nothing as the witness (the rows of the kind `Method`, and under a conformance active where the class is declared): extension_own_include_method, extension_method_witness_where_declared",
        "an own include a superclass's extension already brings: superclass_scoped_extension_order",
        "conditional extensions: extension_conditional_same_method, conditional_extension_include_dispatch, conditional_extension_own_override",
        "a module another extension brings as what implements an abstract method: scoped_extensions_not_ambiguous, extension_witness_other_module",
        "an inference variable as the module's argument: the conformance is declared with written arguments; the call sites infer `T <: M` in witness_matrix_generic",
    ],
    "generic": [
        "path own: as the class target",
        "paths sub_own_ext, ext_sub_inc: as the class target",
        "the subclass paths beyond a reduced list: the same rule as path ext (one file per scope keeps the checker's time down)",
        "the direct call column for args param x witness sup: as concrete",
    ],
    "abstract": [
        "path own, sub_own_ext, ext_sub_inc: as the class target",
        "args concrete/param: as the class and generic targets",
    ],
    "module": [
        "witness sup: a module has no superclass",
        "a module the including class includes before the target: step 3 again (in front of `M` under a scoped extension; behind it under a top-level one, whose module is ordered as the class's own includes)",
        "witness inc: a module the including class includes is `cls` one entry later",
        "the direct call column where both the class and the extension define the method: the extension is of the module, the method the class's own; not a witness question",
        "args concrete/param, paths sub_own_ext/ext_sub_inc: as the class target",
    ],
}

n = 0
out_qz = []
out_exp = []


def left(path, wit, req):
    """The cells whose witness the override table does not pair: no witness
    in #536 step 3's table, left to the pull requests that add them with
    their checks (a module the extension includes beside `M`: #557's
    family; a method the class inherits for an abstract one)."""
    return bool(wit & {"emod", "prev"}) or (path != "own" and "sup" in wit and req == "abstract")


def cell(target, path, wit, req, args, scope):
    """Emit one cell; returns nothing. wit is a set of sources."""
    global n
    if left(path, wit, req):
        return
    i = n
    n += 1
    generic_m = args in ("concrete", "param")
    mp = "[T]" if generic_m else ""
    par_m = "(x: T)" if generic_m else ""
    call = "(1)" if generic_m else ""
    # The argument type as the class and the extension write it.
    if args == "concrete":
        aty, marg = "Int", "[Int]"
    elif args == "param":
        aty, marg = "U", "[U]"
    else:
        aty, marg = None, ""
    par_c = f"(x: {aty})" if generic_m else ""
    cp = "[U]" if target == "generic" else ""
    inst = "[Int]" if target == "generic" else ""
    # What `M` is called with at the call sites.
    mty = f"M{i}" + ("[Int]" if generic_m else "")
    L = []
    w = L.append
    # The module.
    w(f"module M{i}{mp}")
    if req == "abstract":
        w(f"  abstract def m{par_m} -> String")
    else:
        w(f"  def m{par_m} -> String = \"M\"")
    w("end")
    if "nmod" in wit:
        w(f"module N{i}{mp}")
        w(f"  include M{i}{mp}")
        w(f"  def m{par_m} -> String = \"N\"")
        w("end")
    if "emod" in wit:
        w(f"module E{i}{mp}")
        w(f"  def m{par_m} -> String = \"E2\"")
        w("end")
    if "prev" in wit:
        w(f"module P{i}{mp}")
        w(f"  def m{par_m} -> String = \"E0\"")
        w("end")
    if "inc" in wit:
        w(f"module I{i}{cp if args == 'param' else ''}")
        w(f"  def m{par_c} -> String = \"inc\"")
        w("end")
    own_include = path == "own"
    # The conforming class and its surroundings.
    sup = "sup" in wit
    if sup:
        w(f"class B{i}{cp}")
        w("  def initialize; end")
        w(f"  def m{par_c} -> String = \"sup\"")
        w("end")
    if target == "module":
        w(f"module T{i}")
        if "own" in wit:
            w(f"  def m{par_c} -> String = \"T\"")
        w("end")
        w(f"class C{i}")
        w(f"  include T{i}")
        w("  def initialize; end")
        if "cls" in wit:
            w(f"  def m{par_c} -> String = \"cls\"")
        w("end")
        tname = f"T{i}"
        ext_target = f"T{i}"
    else:
        if target == "abstract":
            head = f"abstract class A{i}"
            tname = f"A{i}"
        else:
            head = f"class C{i}{cp}"
            tname = f"C{i}"
        if sup:
            head += f" < B{i}{cp}"
        w(head)
        if own_include:
            w(f"  include M{i}{marg}")
        if "inc" in wit:
            w(f"  include I{i}{cp if args == 'param' else ''}")
        w("  def initialize; end")
        if "own" in wit:
            w(f"  def m{par_c} -> String = \"own\"")
        w("end")
        if target == "abstract":
            w(f"class C{i} < A{i}")
            w("  def initialize; end")
            w("end")
        ext_target = tname + cp
    # The subclass of the path.
    recv = f"C{i}{inst}"
    if path in ("ext_sub", "ext_sub_own", "ext_sub_inc", "sub_own_ext"):
        if path == "ext_sub_inc":
            w(f"module L{i}")
            w(f"  def m{par_c} -> String = \"subinc\"")
            w("end")
        w(f"class S{i}{cp} < C{i}{cp}")
        if path == "ext_sub_inc":
            w(f"  include L{i}")
        w("  def initialize; end")
        if path == "ext_sub_own":
            w(f"  def m{par_c} -> String = \"sub\"")
        w("end")
        recv = f"S{i}{inst}"
    # The extension.
    ind = "  " if scope == "scoped" else ""
    cty = f"C{i}{inst}"
    if not own_include:
        if scope == "scoped":
            w(f"module X{i}")
        w(f"{ind}extension {ext_target}")
        if "prev" in wit:
            w(f"{ind}  include P{i}{marg}")
        if "nmod" in wit:
            w(f"{ind}  include N{i}{marg}")
        else:
            w(f"{ind}  include M{i}{marg}")
        if "emod" in wit:
            w(f"{ind}  include E{i}{marg}")
        if "ext" in wit:
            w(f"{ind}  def m{par_c} -> String = \"ext\"")
        w(f"{ind}end")
        if path == "sub_own_ext":
            w(f"{ind}extension S{i}{cp}")
            w(f"{ind}  include M{i}{marg}")
            w(f"{ind}  def m{par_c} -> String = \"subext\"")
            w(f"{ind}end")
        if scope == "scoped":
            w(f"  def self.up(x: {cty}) -> {mty} = x")
            w(f"  def self.via(x: {mty}) -> String = x.m{call}")
            w(f"  def self.direct(x: {cty}) -> String = x.m{call}")
            w("end")
        else:
            w(f"def up{i}(x: {cty}) -> {mty} = x")
            w(f"def direct{i}(x: {cty}) -> String = x.m{call}")
    else:
        w(f"def up{i}(x: {cty}) -> {mty} = x")
        w(f"def direct{i}(x: {cty}) -> String = x.m{call}")
    w(f"def via{i}(x: {mty}) -> String = x.m{call}")
    label = f"{target}/{path}/{'+'.join(sorted(wit))}/{req}/{args}/{scope}"
    if not own_include and scope == "scoped":
        up, via_in, direct = f"X{i}.up", f"X{i}.via", f"X{i}.direct"
    else:
        up, via_in, direct = f"up{i}", f"via{i}", f"direct{i}"
    typed, lexical = expect(target, path, wit, req)
    cols = [f"#{{via{i}({up}({recv}.new))}}", f"#{{{via_in}({up}({recv}.new))}}"]
    exp = [typed, typed]
    if lexical is not None:
        cols.append(f"#{{{direct}({recv}.new)}}")
        exp.append(lexical)
    w(f"puts \"{label}: {' '.join(cols)}\"")
    out_qz.extend(L)
    out_exp.append(f"{label}: {' '.join(exp)}")


def expect(target, path, wit, req):
    """What the rules say runs: (through M, direct call typed as the class)."""
    # At the class the conformance hangs from.
    if path == "own":
        # Ordinary dispatch: the class's own, an own include's (included
        # after `M`, so in front), the module's body, an inherited method
        # for an abstract one.
        if "own" in wit:
            at_c = "own"
        elif "inc" in wit:
            at_c = "inc"
        elif req == "default":
            at_c = "M"
        else:
            at_c = "sup"
        return at_c, at_c
    if target == "module" and "cls" in wit:
        at_c = "cls"
    elif "ext" in wit:
        at_c = "ext"
    elif "own" in wit:
        at_c = "T" if target == "module" else "own"
    elif "inc" in wit:
        at_c = "inc"
    elif "nmod" in wit:
        at_c = "N"
    elif req == "default":
        # (A method the class inherits does not take a body's place: the
        # module is in front of the superclass.)
        at_c = "M"
    else:
        raise SystemExit(f"the cell {target}/{path}/{wit}/{req} is not in this matrix")
    if wit & {"emod", "prev"}:
        raise SystemExit(f"the cell {target}/{path}/{wit}/{req} is left to its own pull request")
    below = {"ext_sub_own": "sub", "ext_sub_inc": "subinc", "sub_own_ext": "subext"}.get(path)
    typed = below or at_c
    # The direct call where the extension is active, the receiver typed as
    # the conforming class: the extension's own method statically.
    if target == "module" and "cls" in wit and "ext" in wit:
        lexical = None
    elif "ext" in wit and not (target == "module" and "cls" in wit):
        lexical = "ext"
    elif path == "sub_own_ext":
        # The subclass's own extension is not one of the class the call is
        # typed as: the class's method runs, by ordinary dispatch, and an
        # extension's method overrides nothing.
        lexical = at_c
    else:
        lexical = typed
    return typed, lexical


TYPED_HEADER = """# The #536 step 3 witness matrix with types (generated by
# tools/witness-matrix.py): the requirement is `m -> Int`, every candidate
# returns its own number (or another type where it must not be taken),
# and the call through `M` adds to the result, so a witness the table took
# without a check is a `QIR fact violated` under QUARZ_VERIFY=moves and
# "a value not of its static type" compiled, not the same string. The
# table's invariant: a row's witness is the module's own method, an own
# method of an extension that brings the module (checked at the
# extension, in its parameters), or a method the override table pairs
# with the module's (checked where that table is); it adds no pair of
# its own. The expected output was computed from that rule, not taken
# from a run:
# - each source of a witness, scoped and top-level: its number plus 100;
# - a candidate two classes share through different arguments of a
#   generic superclass (`Base[T]#m -> T` for `A < Base[Int]` and
#   `B < Base[String]`, through extensions of the classes and of a module
#   both include): an inherited method is no pair of the override table,
#   so nothing implements the abstract method for either (#600);
# - an extension's own generic method (`extension Base[T]; include
#   MG[T]; def g -> T`): checked once in the extension's parameters, right
#   for both instantiations;
# - a subclass outside a conditional extension's bound that a value
#   reaches all the same (through a contravariant parameter; through a
#   bound that holds only where a scoped extension is active): the
#   override table does not pair its own method (of another type) with
#   the module's, so the module's own runs;
# - an extension's own method for a module it brings only through
#   another extension, generic or with a bound: its number plus 100 (the
#   wrong-typed ones are refused: diagnostics.rs).
"""


def typed(qz, exp):
    L = []
    E = []
    w = L.append
    w("module M")
    w("  abstract def m -> Int")
    w("end")
    w("module D")
    w("  def m -> Int = 1")
    w("end")
    w("def via(x: M) -> Int = x.m + 100")
    w("def via_d(x: D) -> Int = x.m + 100")
    w("def show(x: M) -> String")
    w("  begin")
    w("    via(x).to_s")
    w("  rescue NotImplementedError => e")
    w("    \"unimplemented\"")
    w("  end")
    w("end")
    i = 0
    # Each source, abstract (`M`) and with a body (`D`), scoped and top-level.
    for scope in ("scoped", "top"):
        for src, value in (("ext", 2), ("own", 3), ("inc", 4), ("nmod", 5), ("default", 1), ("sub", 6)):
            for req in ("abstract", "default"):
                if src == "default" and req == "abstract":
                    continue
                i += 1
                mod = "M" if req == "abstract" else "D"
                viaf = "via" if req == "abstract" else "via_d"
                ind = "  " if scope == "scoped" else ""
                if src == "inc":
                    w(f"module I{i}")
                    w("  def m -> Int = 4")
                    w("end")
                if src == "nmod":
                    w(f"module N{i}")
                    w(f"  include {mod}")
                    w("  def m -> Int = 5")
                    w("end")
                w(f"class C{i}")
                if src == "inc":
                    w(f"  include I{i}")
                w("  def initialize; end")
                if src == "own":
                    w("  def m -> Int = 3")
                w("end")
                recv = f"C{i}"
                if src == "sub":
                    w(f"class S{i} < C{i}")
                    w("  def initialize; end")
                    w("  def m -> Int = 6")
                    w("end")
                    recv = f"S{i}"
                if scope == "scoped":
                    w(f"module X{i}")
                w(f"{ind}extension C{i}")
                w(f"{ind}  include {'N' + str(i) if src == 'nmod' else mod}")
                # (Under `sub` the class itself needs a witness of an
                # abstract method: the extension's.)
                if src == "ext" or (src == "sub" and req == "abstract"):
                    w(f"{ind}  def m -> Int = 2")
                w(f"{ind}end")
                if scope == "scoped":
                    w(f"  def self.up(x: C{i}) -> {mod} = x")
                    w("end")
                    up = f"X{i}.up"
                else:
                    w(f"def up{i}(x: C{i}) -> {mod} = x")
                    up = f"up{i}"
                label = f"typed/{src}/{req}/{scope}"
                w(f"puts \"{label}: #{{{viaf}({up}({recv}.new))}}\"")
                E.append(f"{label}: {value + 100}")
    # A candidate shared through a generic superclass's arguments: an
    # inherited method is no pair of the override table.
    w("class Base[T]")
    w("  @v: T")
    w("  def initialize(@v: T); end")
    w("  def v -> T = @v")
    w("  def m -> T = @v")
    w("end")
    w("class A < Base[Int]")
    w("  def initialize; super(1); end")
    w("end")
    w("class B < Base[String]")
    w("  def initialize; super(\"s\"); end")
    w("end")
    w("module Sh")
    w("  extension A")
    w("    include M")
    w("  end")
    w("  extension B")
    w("    include M")
    w("  end")
    w("  def self.a(x: A) -> M = x")
    w("  def self.b(x: B) -> M = x")
    w("end")
    w("puts \"typed/shared/inherited/class: #{show(Sh.a(A.new))} #{show(Sh.b(B.new))}\"")
    E.append("typed/shared/inherited/class: unimplemented unimplemented")
    w("module Seq")
    w("end")
    w("class K1 < Base[Int]")
    w("  include Seq")
    w("  def initialize; super(1); end")
    w("end")
    w("class K2 < Base[String]")
    w("  include Seq")
    w("  def initialize; super(\"s\"); end")
    w("end")
    w("module Sq")
    w("  extension Seq")
    w("    include M")
    w("  end")
    w("  def self.up(x: Seq) -> M = x")
    w("end")
    w("puts \"typed/shared/inherited/module: #{show(Sq.up(K1.new))} #{show(Sq.up(K2.new))}\"")
    E.append("typed/shared/inherited/module: unimplemented unimplemented")
    # An extension's own generic method: one check, in its parameters.
    w("module MG[U]")
    w("  abstract def g -> U")
    w("end")
    w("class GB[T]")
    w("  @v: T")
    w("  def initialize(@v: T); end")
    w("  def v -> T = @v")
    w("end")
    w("class GA < GB[Int]")
    w("  def initialize; super(7); end")
    w("end")
    w("class GS < GB[String]")
    w("  def initialize; super(\"s\"); end")
    w("end")
    w("module Sg")
    w("  extension GB[T]")
    w("    include MG[T]")
    w("    def g -> T = v")
    w("  end")
    w("  def self.i(x: GB[Int]) -> MG[Int] = x")
    w("  def self.s(x: GB[String]) -> MG[String] = x")
    w("end")
    w("def via_i(x: MG[Int]) -> Int = x.g + 100")
    w("def via_s(x: MG[String]) -> String = x.g + \"!\"")
    w("puts \"typed/shared/extension: #{via_i(Sg.i(GA.new))} #{via_s(Sg.s(GS.new))}\"")
    E.append("typed/shared/extension: 107 s!")
    # A subclass outside a conditional extension's bound, reached through
    # a contravariant parameter.
    w("class Animal")
    w("  def initialize; end")
    w("end")
    w("class Dog < Animal")
    w("  def initialize; end")
    w("end")
    w("class Sink[in T]")
    w("  def initialize; end")
    w("  def put(x: T) -> Void")
    w("  end")
    w("end")
    w("extension Sink[T <: Animal]")
    w("  include D")
    w("end")
    w("class CSub < Sink[Object]")
    w("  def initialize; end")
    w("  def m -> String = \"s\"")
    w("end")
    w("def up_sink(s: Sink[Dog]) -> D = s")
    w("puts \"typed/outside-bound/variance: #{via_d(up_sink(Sink[Dog].new))} #{via_d(up_sink(CSub.new))}\"")
    E.append("typed/outside-bound/variance: 101 101")
    # ... and through a bound that holds only where a scoped extension is
    # active.
    w("module Marked")
    w("end")
    w("class Bx[T]")
    w("  def initialize; end")
    w("end")
    w("extension Bx[T <: Marked]")
    w("  include D")
    w("end")
    w("class BSub < Bx[String]")
    w("  def initialize; end")
    w("  def m -> String = \"s\"")
    w("end")
    w("module Sm")
    w("  extension String")
    w("    include Marked")
    w("  end")
    w("  def self.up(b: Bx[String]) -> D = b")
    w("end")
    w("puts \"typed/outside-bound/scoped: #{via_d(Sm.up(BSub.new))}\"")
    E.append("typed/outside-bound/scoped: 101")
    # An extension's own method for a module it brings only through
    # another extension (`extension TN[T]; include TM[T]`), that one
    # generic or with a bound, the target concrete or generic: the pair is
    # checked at the extension with the module's arguments through the
    # bringing extension's parameters.
    w("module TM[U]")
    w("  abstract def tm -> U")
    w("end")
    w("def via_tm(x: TM[Int]) -> Int = x.tm + 100")
    for tag, bound in (("generic", ""), ("bound", " <: Int")):
        n = "TN" + tag.capitalize()
        w(f"module {n}[T]")
        w("end")
        w(f"class TC{tag}")
        w("  def initialize; end")
        w("end")
        w(f"class TG{tag}[V]")
        w("  @v: V")
        w("  def initialize(@v: V); end")
        w("  def v -> V = @v")
        w("end")
        w(f"module St{tag}")
        w(f"  extension {n}[T{bound}]")
        w("    include TM[T]")
        w("  end")
        w(f"  extension TC{tag}")
        w(f"    include {n}[Int]")
        w("    def tm -> Int = 8")
        w("  end")
        w(f"  extension TG{tag}[V{bound}]")
        w(f"    include {n}[V]")
        w("    def tm -> V = v")
        w("  end")
        w(f"  def self.c(x: TC{tag}) -> TM[Int] = x")
        w(f"  def self.g(x: TG{tag}[Int]) -> TM[Int] = x")
        w("end")
        w(f"puts \"typed/through-extension/{tag}: #{{via_tm(St{tag}.c(TC{tag}.new))}} #{{via_tm(St{tag}.g(TG{tag}[Int].new(9)))}}\"")
        E.append(f"typed/through-extension/{tag}: 108 109")
    with open(qz, "w") as f:
        f.write(TYPED_HEADER + "\n".join(L) + "\n")
    with open(exp, "w") as f:
        f.write("\n".join(E) + "\n")


def main():
    target, qz, exp = sys.argv[1:4]
    if target == "typed":
        return typed(qz, exp)
    scopes = ["scoped", "top"]
    if target in ("class_scoped", "class_top", "class_args"):
        variant, target = target, "class"
        full = [({"ext"}, "abstract"), ({"ext"}, "default"), ({"own"}, "abstract"),
                ({"own"}, "default"), ({"inc"}, "abstract"), ({"inc"}, "default"),
                ({"sup"}, "abstract"), ({"sup"}, "default"), ({"emod"}, "abstract"),
                ({"emod"}, "default"), ({"nmod"}, "abstract"), ({"nmod"}, "default"),
                (set(), "default"), ({"prev"}, "abstract"), ({"prev"}, "default"),
                ({"ext", "own"}, "abstract"), ({"ext", "inc"}, "default"),
                ({"own", "inc"}, "abstract"), ({"own", "emod"}, "default"),
                ({"emod", "sup"}, "abstract"), ({"ext", "emod"}, "default")]
        if variant == "class_args":
            # The module's arguments: concrete ones, a reduced list.
            for wit, req in (({"own"}, "abstract"), (set(), "default"), ({"sup"}, "abstract")):
                cell(target, "own", wit, req, "concrete", "none")
            for scope in scopes:
                for wit, req in (({"ext"}, "abstract"), ({"own"}, "default"), ({"inc"}, "abstract"),
                                 ({"sup"}, "abstract"), ({"emod"}, "abstract"), ({"nmod"}, "default"),
                                 (set(), "default"), ({"prev"}, "abstract")):
                    cell(target, "ext", wit, req, "concrete", scope)
                for wit, req in (({"ext"}, "abstract"), ({"own"}, "abstract"), (set(), "default")):
                    cell(target, "ext_sub_own", wit, req, "concrete", scope)
        else:
            scope = "scoped" if variant == "class_scoped" else "top"
            if scope == "scoped":
                # Path own (control): no extension, so once.
                for wit, req in (({"own"}, "abstract"), ({"own"}, "default"), (set(), "default"),
                                 ({"inc"}, "abstract"), ({"own", "inc"}, "default"),
                                 ({"sup"}, "abstract"), ({"sup"}, "default")):
                    cell(target, "own", wit, req, "none", "none")
            for wit, req in full:
                cell(target, "ext", wit, req, "none", scope)
            for wit, req in (({"ext"}, "abstract"), ({"own"}, "default"), ({"sup"}, "abstract"),
                             ({"emod"}, "abstract"), (set(), "default")):
                cell(target, "ext_sub", wit, req, "none", scope)
            for wit, req in (({"ext"}, "abstract"), ({"ext"}, "default"), ({"own"}, "abstract"),
                             ({"inc"}, "default"), ({"sup"}, "abstract"), ({"emod"}, "abstract"),
                             ({"nmod"}, "default"), (set(), "default"), ({"prev"}, "abstract")):
                cell(target, "ext_sub_own", wit, req, "none", scope)
            for wit, req in (({"ext"}, "abstract"), ({"own"}, "default"), (set(), "default"),
                             ({"sup"}, "abstract")):
                cell(target, "ext_sub_inc", wit, req, "none", scope)
            for wit, req in (({"ext"}, "abstract"), ({"ext"}, "default"), ({"own"}, "abstract")):
                cell(target, "sub_own_ext", wit, req, "none", scope)
    elif target in ("generic_scoped", "generic_top"):
        scope = "scoped" if target == "generic_scoped" else "top"
        target = "generic"
        for args in ("none", "concrete", "param"):
            for wit, req in (({"ext"}, "abstract"), ({"ext"}, "default"), ({"own"}, "abstract"),
                             ({"own"}, "default"), ({"sup"}, "abstract"), ({"emod"}, "abstract"),
                             ({"nmod"}, "default"), (set(), "default"),
                             ({"ext", "own"}, "default")):
                cell(target, "ext", wit, req, args, scope)
            for wit, req in (({"ext"}, "abstract"), (set(), "default")):
                cell(target, "ext_sub", wit, req, args, scope)
            for wit, req in (({"ext"}, "abstract"), ({"own"}, "abstract"), ({"emod"}, "abstract"),
                             (set(), "default")):
                cell(target, "ext_sub_own", wit, req, args, scope)
    elif target == "abstract":
        for scope in scopes:
            for path in ("ext", "ext_sub", "ext_sub_own"):
                for wit, req in (({"ext"}, "abstract"), ({"ext"}, "default"), ({"own"}, "abstract"),
                                 ({"own"}, "default"), ({"sup"}, "abstract"), ({"emod"}, "abstract"),
                                 ({"nmod"}, "default"), (set(), "default"), ({"ext", "own"}, "abstract")):
                    cell(target, path, wit, req, "none", scope)
    elif target == "module":
        for scope in scopes:
            for path in ("ext", "ext_sub", "ext_sub_own"):
                for wit, req in (({"ext"}, "abstract"), ({"ext"}, "default"), ({"own"}, "abstract"),
                                 ({"own"}, "default"), ({"cls"}, "abstract"), ({"cls"}, "default"),
                                 ({"cls", "ext"}, "abstract"), ({"cls", "own"}, "default"),
                                 ({"ext", "own"}, "abstract"), ({"emod"}, "abstract"),
                                 ({"nmod"}, "default"), (set(), "default")):
                    cell(target, path, wit, req, "none", scope)
    else:
        raise SystemExit("target?")
    skipped = "\n".join(f"# - {s}" for s in SKIPPED[target])
    variant = sys.argv[1]
    note = {"class_scoped": " (scoped extensions; top-level ones: witness_matrix_instance_class_top; the module's arguments: _class_args)",
            "class_top": " (top-level extensions)",
            "class_args": " (the module's arguments, both scopes)",
            "generic_scoped": " (scoped extensions; top-level ones: witness_matrix_instance_generic_top)",
            "generic_top": " (top-level extensions)"}.get(variant, "")
    with open(qz, "w") as f:
        f.write(HEADER.format(target=target, note=note, skipped=skipped) + "\n" + "\n".join(out_qz) + "\n")
    with open(exp, "w") as f:
        f.write("\n".join(out_exp) + "\n")


main()
